script:
const q=document.querySelector('#q'),zip=document.querySelector('#zip'),svc=document.querySelector('#svc'),state=document.querySelector('#state'),cards=[...document.querySelectorAll('.p-card')],grid=document.querySelector('#cards'),n=document.querySelector('#n'),status=document.querySelector('#status'),intl=document.querySelector('#international'),intlGrid=document.querySelector('#intl-cards'),intlN=document.querySelector('#intl-n'),original=new Map(cards.map((c,i)=>[c,i]));
const norm=v=>v.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const rad=v=>v*Math.PI/180, miles=(a,b)=>{const x=rad(b.lat-a.lat),y=rad(b.lon-a.lon),h=Math.sin(x/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(y/2)**2;return 3958.8*2*Math.asin(Math.sqrt(h))};
let seq=0;const cache=new Map();async function zipPoint(z){if(!cache.has(z))cache.set(z,fetch('https://api.zippopotam.us/us/'+z).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>({lat:+d.places[0].latitude,lon:+d.places[0].longitude,place:d.places[0]['place name'],state:d.places[0]['state abbreviation']})));return cache.get(z)}
function reset(){cards.sort((a,b)=>original.get(a)-original.get(b)).forEach(c=>{c.hidden=false;c.querySelector('.distance').hidden=true;grid.appendChild(c)});intl.hidden=true;status.textContent=''}
const hasService=(c,service)=>!service||c.dataset.filters.split('|').includes(service);
const hasState=c=>!state.value||(c.dataset.country==='USA'&&c.dataset.region===state.value);
function textFilter(){const needle=norm(q.value),service=svc.value;let count=0;cards.forEach(c=>{const show=(!needle||c.dataset.search.includes(needle))&&hasService(c,service)&&hasState(c);c.hidden=!show;if(show)count++});n.textContent=count;status.textContent=needle||service||state.value?(count?count+' matching '+(count===1?'center.':'centers.'):'No listed centers match that search.'):''}
async function zipFilter(z,mySeq){status.textContent='Finding the nearest listed centers…';try{const origin=await zipPoint(z);if(mySeq!==seq)return;const service=svc.value,eligible=cards.filter(c=>hasService(c,service)&&hasState(c)),us=eligible.filter(c=>c.dataset.country==='USA'),other=eligible.filter(c=>c.dataset.country!=='USA');cards.forEach(c=>c.hidden=true);us.map(c=>({c,d:miles(origin,{lat:+c.dataset.lat,lon:+c.dataset.lon})})).sort((a,b)=>a.d-b.d).forEach(x=>{x.c.hidden=false;const p=x.c.querySelector('.distance');p.textContent='Approximately '+Math.round(x.d)+' miles';p.hidden=false;grid.appendChild(x.c)});other.forEach(c=>{c.hidden=false;intlGrid.appendChild(c)});intlN.textContent=other.length;intl.hidden=!other.length;n.textContent=us.length;status.textContent=us.length?'Nearest matching US centers first from '+origin.place+', '+origin.state+'. Straight-line distance.':'No listed US centers match that service filter.'}catch{if(mySeq!==seq)return;reset();textFilter();status.textContent='We could not locate that ZIP code. Check the five digits or search by city, state or hospital name.'}}
function run(){const mySeq=++seq,z=zip.value.trim();if(/^\d{5}$/.test(z)){q.value='';zipFilter(z,mySeq)}else{reset();textFilter()}}
q.addEventListener('input',()=>{zip.value='';run()});zip.addEventListener('input',run);svc.addEventListener('change',run);state.addEventListener('change',run);
const initialService=new URLSearchParams(location.search).get('service');
if(initialService&&[...svc.options].some(option=>option.value===initialService)){svc.value=initialService;run()}
